import{_ as g,A as p,o as n,c as d,O as t,b as a,w as r,Z as l,E as e,a as i}from"./chunks/framework.2c2d5a61.js";const c="/cao_note/java-10w/image206.jpeg",h="/cao_note/java-10w/image234.jpeg",E="/cao_note/java-10w/image241.jpeg",q=JSON.parse('{"title":"MySQL","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/07-MySQL.md","filePath":"interview/后端/Java/07-MySQL.md","lastUpdated":1793001193000}'),u={name:"interview/后端/Java/07-MySQL.md"};function L(b,o,A,m,y,I){const s=p("Mermaid");return n(),d("div",null,[o[2]||(o[2]=t(`<h1 id="mysql" tabindex="-1">MySQL <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;MySQL&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点按「定义 → 原理 → 要点 / 易错点」组织，只讲知识点</li></ul></blockquote><hr><h2 id="_1-innodb-与-myisam-区别-★★★" tabindex="-1">1. InnoDB 与 MyISAM 区别 ★★★ <a class="header-anchor" href="#_1-innodb-与-myisam-区别-★★★" aria-label="Permalink to &quot;1. InnoDB 与 MyISAM 区别 ★★★&quot;">​</a></h2><p><strong>InnoDB</strong> 支持<strong>事务</strong>、<strong>行级锁</strong>、外键、崩溃恢复，索引是<strong>聚簇</strong>的（数据即索引）；<strong>MyISAM</strong> 不支持事务、外键和崩溃恢复，只有<strong>表级锁</strong>，索引和数据分离，但无事务开销，某些只读查询略快。MySQL 5.5 之后默认就是 InnoDB，涉及事务的场景只能选 InnoDB。</p><p>按维度对比：</p><ul><li><strong>事务与外键</strong>：InnoDB 每条 SQL 默认封装成事务、自动提交，会影响速度，多条 SQL 最好显式放在 <code>begin</code> / <code>commit</code> 之间组成一个事务；MyISAM 不支持事务和外键，带外键的 InnoDB 表转 MyISAM 会失败。</li><li><strong>索引结构</strong>：InnoDB 是<strong>聚簇索引</strong>，数据文件和索引绑在一起，必须要有主键，主键索引效率高；<strong>辅助索引需要两次查询</strong>，先查到主键再回表取数据，所以主键不应过大，否则其它索引也会跟着变大。MyISAM 是<strong>非聚簇索引</strong>，数据文件分离，索引保存的是数据文件的指针，主键索引和辅助索引相互独立。</li><li><strong>行数统计</strong>：InnoDB 不保存表的具体行数，<code>select count(*) from table</code> 需要全表扫描；MyISAM 用一个变量保存整表行数，执行时直接读出该变量，速度很快。</li><li><strong>全文索引</strong>：InnoDB 不支持全文索引，MyISAM 支持，查询效率上 MyISAM 更高。</li></ul><p>结论：生产环境一律 InnoDB。</p><hr><p><strong>补充（原文详解）</strong></p><ol><li><p>InnoDB支持事务，MyISAM不支持，对于InnoDB每一条SQL语言都默认封装成事务，自动提 交，这样会影响速度，所以最好把多条SQL语言放在begin和commit之间，组成一个事务；</p></li><li><p>InnoDB支持外键，而MyISAM不支持。对一个包含外键的InnoDB表转为MYISAM会失败；</p></li><li><p>InnoDB是聚集索引，数据文件是和索引绑在一起的，必须要有主键，通过主键索引效率很高。</p></li></ol><p>但是辅助索引需要两次查询，先查询到主键，然后再通过主键查询到数据。因此，主键不应该过大，因为主键太大，其他索引也都会很大。而MyISAM是非聚集索引，数据文件是分离的， 索引保存的是数据文件的指针。主键索引和辅助索引是独立的。</p><ol start="4"><li><p>InnoDB不保存表的具体行数，执行select count(*) from table时需要全表扫描。而MyISAM用 一个变量保存了整个表的行数，执行上述语句时只需要读出该变量即可，速度很快；</p></li><li><p>Innodb不支持全文索引，而MyISAM支持全文索引，查询效率上MyISAM要高；</p></li></ol><h2 id="_2-索引为什么用-b-树-★★★" tabindex="-1">2. 索引为什么用 B+ 树 ★★★ <a class="header-anchor" href="#_2-索引为什么用-b-树-★★★" aria-label="Permalink to &quot;2. 索引为什么用 B+ 树 ★★★&quot;">​</a></h2><p>选 <strong>B+ 树</strong>的核心是<strong>磁盘 IO</strong>：树越矮，访问磁盘的次数越少。</p><p>排除其它结构的原因：</p><ul><li><strong>哈希</strong>：等值查询很快，但不支持<strong>范围查询</strong>和排序。</li><li><strong>二叉搜索树 / 红黑树</strong>：每个节点最多两个分支，树高随数据量增长，<strong>磁盘 IO</strong> 次数跟着树高走，数据量大时 IO 过多。</li><li><strong>B 树</strong>：多路搜索树，但每个节点既存索引又存数据，一页能放的索引项少，树也高。</li><li><strong>B+ 树</strong>：非叶子节点只存索引、不存数据，一页能塞更多索引，树更矮（<strong>3 层</strong>能存千万级数据）；数据全在叶子节点，叶子之间用<strong>双向链表</strong>连起来，天然支持<strong>范围查询</strong>和排序。</li></ul><p>因此按「桩编号 + 时间范围」这类条件查询时，可以沿叶子链表顺序扫描，这也是时间字段要放进<strong>联合索引</strong>的原因。</p><hr><h2 id="_3-聚簇索引、回表、覆盖索引-★★★" tabindex="-1">3. 聚簇索引、回表、覆盖索引 ★★★ <a class="header-anchor" href="#_3-聚簇索引、回表、覆盖索引-★★★" aria-label="Permalink to &quot;3. 聚簇索引、回表、覆盖索引 ★★★&quot;">​</a></h2><p><strong>聚簇索引</strong>（主键索引）的叶子节点存<strong>整行数据</strong>，一张表只能有一个。<strong>二级索引</strong>的叶子存「索引列 + 主键值」，用它查到主键后还得回聚簇索引再捞一次整行，这叫<strong>回表</strong>。如果查询需要的列全在二级索引里，就不用回表，这就是<strong>覆盖索引</strong>，性能最好，也是最常用的优化手段。</p><p>主键建议<strong>自增</strong>：顺序插入减少<strong>页分裂</strong>；<strong>UUID</strong> 随机插入会频繁页分裂、产生碎片，还占空间，所以不建议做主键。</p><hr><h2 id="_4-最左前缀与联合索引-★★★" tabindex="-1">4. 最左前缀与联合索引 ★★★ <a class="header-anchor" href="#_4-最左前缀与联合索引-★★★" aria-label="Permalink to &quot;4. 最左前缀与联合索引 ★★★&quot;">​</a></h2><p><strong>联合索引</strong> (a,b,c) 按 a、b、c 的字典序排列，所以查询必须从<strong>最左列</strong>开始连续匹配才能用上索引：(a)、(a,b)、(a,b,c) 能命中，直接查 b、c 不行。</p><p><strong>范围查询</strong>会「中断」匹配：<code>a=1 and b&gt;2</code> 能用上 a 和 b，但 b 后面的 c 就用不上了。所以设计联合索引时，<strong>等值条件</strong>、<strong>区分度高</strong>的列放最左，<strong>范围查询</strong>列尽量往后放，例如「桩编号（等值）+ 订单状态（等值）+ 创建时间（范围）」这种顺序。</p><hr><h2 id="_5-索引失效场景-★★★-【简历亮点-高频追问】" tabindex="-1">5. 索引失效场景 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_5-索引失效场景-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;5. 索引失效场景 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p>常见失效场景：</p><ul><li>索引列上做<strong>函数或运算</strong>：<code>YEAR(create_time)=2024</code>、<code>id+1=5</code>；</li><li><strong>隐式类型转换</strong>：字符串字段没加引号，比如手机号传成数字，或反过来；</li><li>不满足<strong>最左前缀</strong>；</li><li>范围查询后面的列；</li><li>使用 <code>!=</code>、<code>NOT IN</code>；</li><li>前导模糊 <code>LIKE &#39;%xx&#39;</code>；</li><li><code>OR</code> 连接了非索引列；</li><li>数据量特别小时，优化器判断<strong>全表扫描</strong>更快。</li></ul><p><strong>隐式类型转换</strong>是最容易忽略的一种：字段类型和参数类型不一致就会触发隐式转换，索引直接失效，现象是建了索引查询依然很慢，修复方式是保证<strong>参数类型和字段类型一致</strong>。判断有没有走索引，用 <strong>EXPLAIN</strong> 看 type 和 key。</p><hr><h2 id="_6-explain-关键字段-★★★" tabindex="-1">6. EXPLAIN 关键字段 ★★★ <a class="header-anchor" href="#_6-explain-关键字段-★★★" aria-label="Permalink to &quot;6. EXPLAIN 关键字段 ★★★&quot;">​</a></h2><p>重点看四列：</p><ul><li><strong>type</strong>：访问类型，从好到差为 <code>system</code>、<code>const</code>、<code>eq_ref</code>、<code>ref</code>、<code>range</code>、<code>index</code>、<code>ALL</code>。看到 <strong>ALL</strong> 基本就是缺索引或<strong>索引失效</strong>，即<strong>全表扫描</strong>。</li><li><strong>key</strong>：实际使用的索引。</li><li><strong>rows</strong>：预估扫描行数，越小越好。</li><li><strong>Extra</strong>：<code>Using index</code> 表示<strong>覆盖索引</strong>，是好的；<code>Using filesort</code> 表示需要<strong>额外排序</strong>，要优化；<code>Using temporary</code> 表示用了<strong>临时表</strong>，通常是 group by / distinct 没走索引。</li></ul><p>排查慢 SQL 的顺序就是先看 type 是否为 ALL，再看 Extra 有没有 filesort 或 temporary。</p><hr><h2 id="_7-事务-acid-及实现原理-★★★" tabindex="-1">7. 事务 ACID 及实现原理 ★★★ <a class="header-anchor" href="#_7-事务-acid-及实现原理-★★★" aria-label="Permalink to &quot;7. 事务 ACID 及实现原理 ★★★&quot;">​</a></h2><p><strong>ACID</strong> 各自的实现机制：</p><ul><li><strong>原子性（A）</strong>：靠 <strong>undo log</strong>，操作失败可以回滚。</li><li><strong>持久性（D）</strong>：靠 <strong>redo log</strong>，提交后即使崩溃也不丢。</li><li><strong>隔离性（I）</strong>：靠<strong>锁</strong>加 <strong>MVCC</strong>。</li><li><strong>一致性（C）</strong>：由 A、I、D 共同保证的结果，不是单独某个机制。</li></ul><p>两种日志的分工：<strong>redo log</strong> 记「改了什么」，用于<strong>崩溃恢复</strong>；<strong>undo log</strong> 记「改前的值」，用于回滚和 <strong>MVCC</strong>。</p><p>事务不能写太大：<strong>大事务</strong>会长时间占锁、undo 膨胀、还可能拖慢<strong>主从复制</strong>，批量场景应<strong>分批提交</strong>。</p><hr><h2 id="_8-隔离级别与并发问题-★★★" tabindex="-1">8. 隔离级别与并发问题 ★★★ <a class="header-anchor" href="#_8-隔离级别与并发问题-★★★" aria-label="Permalink to &quot;8. 隔离级别与并发问题 ★★★&quot;">​</a></h2><p>三种并发问题：</p><ul><li><strong>脏读</strong>：读到别的事务还没提交的数据。</li><li><strong>不可重复读</strong>：同一事务内两次读同一行，中间别的事务 update 了，两次结果不同。</li><li><strong>幻读</strong>：同一事务内两次读，中间别的事务 insert / delete，行数变了。</li></ul><p>四个隔离级别：</p><ul><li><strong>READ-UNCOMMITTED（读未提交）</strong>：三种问题都有。</li><li><strong>READ-COMMITTED（读已提交，RC）</strong>：解决脏读，仍可能不可重复读和幻读；Oracle 默认。</li><li><strong>REPEATABLE-READ（可重复读，RR）</strong>：解决脏读和不可重复读，MySQL 默认；InnoDB 配合 <strong>MVCC</strong> 和<strong>间隙锁</strong>基本解决幻读。</li><li><strong>SERIALIZABLE（串行化）</strong>：全部解决，但事务串行执行，性能最差。</li></ul><p>RR 下<strong>间隙锁</strong>较多，并发写容易<strong>死锁</strong>，批量更新场景要控制<strong>锁范围</strong>、缩短事务。</p><hr><p><strong>补充（原文详解）</strong></p><p>SQL 标准定义了四个隔离级别：</p><p>READ-UNCOMMITTED(读取未提交)： 最低的隔离级别，允许读取尚未提交的数据变更，可能会导致脏读、幻读或不可重复读。</p><p>READ-COMMITTED(读取已提交)： 允许读取并发事务已经提交的数据，可以阻止脏读，但是幻读或不可重复读仍有可能发生。</p><p>REPEATABLE-READ(可重复读)： 对同一字段的多次读取结果都是一致的，除非数据是被本身事务自己所修改，可以阻止脏读和不可重复读，但幻读仍有可能发生。</p><p>SERIALIZABLE(可串行化)： 最高的隔离级别，完全服从ACID的隔离级别。所有的事务依次逐个执行，这样事务之间就完全不可能产生干扰，也就是说，该级别可以防止脏读、不可重复读以及幻读。</p><table><thead><tr><th>隔离级别</th><th>脏读</th><th>不可重复读</th><th>幻影读</th></tr></thead><tbody><tr><td>READ-UNCOMMITTED</td><td>√</td><td>√</td><td>√</td></tr><tr><td>READ-COMMITTED</td><td>×</td><td>√</td><td>√</td></tr><tr><td>REPEATABLE-READ</td><td>×</td><td>×</td><td>√</td></tr><tr><td>SERIALIZABLE</td><td>×</td><td>×</td><td>×</td></tr></tbody></table><p>MySQL InnoDB 存储引擎的默认支持的隔离级别是 REPEATABLE-READ（可重读）。我们可以通过 SELECT @@tx_isolation; 命令来查看</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">mysql</span><span style="color:#F97583;">&gt;</span><span style="color:#E1E4E8;"> SELECT @@</span><span style="color:#F97583;">tx_isolation</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#F97583;">+-----------------+</span></span>
<span class="line"><span style="color:#F97583;">|</span><span style="color:#E1E4E8;"> @@</span><span style="color:#F97583;">tx_isolation</span><span style="color:#E1E4E8;">  </span><span style="color:#F97583;">|</span></span>
<span class="line"><span style="color:#F97583;">+-----------------+</span></span>
<span class="line"><span style="color:#F97583;">|</span><span style="color:#E1E4E8;"> REPEATABLE</span><span style="color:#F97583;">-</span><span style="color:#E1E4E8;">READ </span><span style="color:#F97583;">|</span></span>
<span class="line"><span style="color:#F97583;">+-----------------+</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">mysql</span><span style="color:#D73A49;">&gt;</span><span style="color:#24292E;"> SELECT @@</span><span style="color:#D73A49;">tx_isolation</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">+-----------------+</span></span>
<span class="line"><span style="color:#D73A49;">|</span><span style="color:#24292E;"> @@</span><span style="color:#D73A49;">tx_isolation</span><span style="color:#24292E;">  </span><span style="color:#D73A49;">|</span></span>
<span class="line"><span style="color:#D73A49;">+-----------------+</span></span>
<span class="line"><span style="color:#D73A49;">|</span><span style="color:#24292E;"> REPEATABLE</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">READ </span><span style="color:#D73A49;">|</span></span>
<span class="line"><span style="color:#D73A49;">+-----------------+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>这里需要注意的是：与 SQL 标准不同的地方在于 InnoDB 存储引擎在 REPEATABLE-READ（可重读） 事务隔离级别下使用的是Next-Key Lock 锁算法，因此可以避免幻读的产生，这与其他数据库系统(如 SQL Server) 是不同的。所以说InnoDB 存储引擎的默认支持的隔离级别是 REPEATABLE- READ（可重读） 已经可以完全保证事务的隔离性要求，即达到了 SQL标准的 SERIALIZABLE(可串行化) 隔离级别。因为隔离级别越低，事务请求的锁越少，所以大部分数据库系统的隔离级别都是</p><p>READ-COMMITTED(读取提交内容)，但是你要知道的是InnoDB 存储引擎默认使用 REPEAaTABLE-READ（可重读） 并不会有任何性能损失。</p><p>InnoDB 存储引擎在分布式事务的情况下一般会用到 SERIALIZABLE(可串行化) 隔离级别。</p><h2 id="_9-mvcc-多版本并发控制-★★★-【简历亮点-高频追问】" tabindex="-1">9. MVCC 多版本并发控制 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_9-mvcc-多版本并发控制-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;9. MVCC 多版本并发控制 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>MVCC</strong> 的作用是让「读不加锁、写不阻塞读」，读写互不阻塞。</p><p>实现依赖三样东西：</p><ul><li>每行记录有<strong>隐藏列</strong>：最近修改它的事务 id、指向 <strong>undo log</strong> 旧版本的回滚指针，构成<strong>版本链</strong>；</li><li><strong>undo log</strong> 保存历史版本；</li><li><strong>ReadView</strong>（快照）决定当前事务能看到哪些版本。</li></ul><p><strong>RC 与 RR 的区别就在 ReadView 的生成时机</strong>：RC 每次 SELECT 都新建一个，所以能看到别的事务新提交的数据；RR 在事务内第一次 SELECT 时建一次然后复用，所以可重复读。</p><p>由此可以解释两个现象：长事务里读到的始终是老数据；长事务会让 <strong>undo 版本链</strong>变长、拖慢查询。所以事务应尽量短，尤其不要在事务里做远程调用。</p><hr><h2 id="_10-mysql-锁-行锁、间隙锁、临键锁-★★★" tabindex="-1">10. MySQL 锁：行锁、间隙锁、临键锁 ★★★ <a class="header-anchor" href="#_10-mysql-锁-行锁、间隙锁、临键锁-★★★" aria-label="Permalink to &quot;10. MySQL 锁：行锁、间隙锁、临键锁 ★★★&quot;">​</a></h2><p><strong>InnoDB</strong> 支持<strong>行锁</strong>，按锁范围分三种：</p><ul><li><strong>记录锁（Record Lock）</strong>：锁住单行记录；</li><li><strong>间隙锁（Gap Lock）</strong>：锁的是索引记录之间的空隙，防止别的事务往空隙里插入；</li><li><strong>临键锁（Next-Key Lock）</strong>：记录锁 + 间隙锁，锁「左开右闭」的区间，<strong>RR</strong> 下用来解决<strong>幻读</strong>。</li></ul><p>死锁排查用 <code>SHOW ENGINE INNODB STATUS</code>，看 <code>LATEST DETECTED DEADLOCK</code> 段。</p><p>减少死锁的做法：更新条件尽量走<strong>主键</strong>或<strong>唯一索引</strong>，把<strong>范围锁</strong>降成<strong>单行锁</strong>；死锁真发生时 MySQL 会自动回滚其中一个事务，业务侧做好重试。</p><hr><h2 id="_11-三大范式与反范式-★★☆" tabindex="-1">11. 三大范式与反范式 ★★☆ <a class="header-anchor" href="#_11-三大范式与反范式-★★☆" aria-label="Permalink to &quot;11. 三大范式与反范式 ★★☆&quot;">​</a></h2><p>三大范式逐级递进：</p><ul><li><strong>1NF</strong>：列不可再分，每个字段都是原子值；</li><li><strong>2NF</strong>：在 1NF 基础上消除<strong>部分依赖</strong>，非主属性完全依赖主键；</li><li><strong>3NF</strong>：在 2NF 基础上消除<strong>传递依赖</strong>，非主属性不能依赖其它非主属性。</li></ul><p><strong>反范式</strong>就是故意<strong>冗余字段</strong>（比如订单表冗余桩编号、用户名），用空间换时间、减少 <strong>join</strong>。实践中常用「范式打底 + 关键查询适度冗余」的折中。</p><hr><h2 id="_12-三大日志-redo、undo、binlog-★★★" tabindex="-1">12. 三大日志：redo、undo、binlog ★★★ <a class="header-anchor" href="#_12-三大日志-redo、undo、binlog-★★★" aria-label="Permalink to &quot;12. 三大日志：redo、undo、binlog ★★★&quot;">​</a></h2><ul><li><strong>redo log</strong>：InnoDB 的<strong>物理日志</strong>，记「数据页改了什么」，顺序写、循环写，用于<strong>崩溃恢复</strong>，保证<strong>持久性</strong>。</li><li><strong>undo log</strong>：记「改前的值」，用于回滚和 <strong>MVCC</strong>。</li><li><strong>binlog</strong>：Server 层的<strong>逻辑日志</strong>，记录所有变更，追加写，用于<strong>主从复制</strong>和数据恢复，主流格式是 <strong>row</strong>。</li></ul><p><strong>redo 与 binlog 靠两阶段提交保证一致</strong>，否则可能出现主库已提交、从库没收到的半成功状态，导致主从数据不一致。两者定位的区别是：redo 是<strong>引擎层物理日志</strong>、binlog 是 <strong>Server 层逻辑日志</strong>。</p><hr><h2 id="_13-主从复制原理-★★★" tabindex="-1">13. 主从复制原理 ★★★ <a class="header-anchor" href="#_13-主从复制原理-★★★" aria-label="Permalink to &quot;13. 主从复制原理 ★★★&quot;">​</a></h2><p>流程：主库写 <strong>binlog</strong> → 从库 <strong>IO 线程</strong>拉取 binlog，写到本地 <strong>relay log</strong> → 从库 <strong>SQL 线程</strong>重放 relay log。</p>`,86)),(n(),a(l,null,{default:r(()=>[e(s,{id:"mermaid-549",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E4%B8%BB%E5%BA%93%3Cbr%2F%3E%E5%86%99%20binlog%5D%20--%3E%20B%5B%E4%BB%8E%E5%BA%93%20IO%20%E7%BA%BF%E7%A8%8B%3Cbr%2F%3E%E6%8B%89%E5%8F%96%20binlog%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%86%99%E6%9C%AC%E5%9C%B0%20relay%20log%5D%0A%20%20%20%20C%20--%3E%20D%5B%E4%BB%8E%E5%BA%93%20SQL%20%E7%BA%BF%E7%A8%8B%3Cbr%2F%3E%E9%87%8D%E6%94%BE%20relay%20log%5D%0A"})]),fallback:r(()=>o[0]||(o[0]=[i(" Loading... ")])),_:1})),o[3]||(o[3]=t('<p>作用是<strong>读写分离</strong>、备份、高可用。</p><p>延迟原因：从库重放慢（早期<strong>单线程</strong>重放）、存在<strong>大事务</strong>、从库硬件较差、网络延迟。</p><p>读写分离要注意：写完立刻要读的场景（比如下单后马上查订单）必须强制走<strong>主库</strong>，否则<strong>主从延迟</strong>会读到旧数据。</p><hr><h2 id="_14-慢查询优化思路-★★★-【简历亮点-高频追问】" tabindex="-1">14. 慢查询优化思路 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_14-慢查询优化思路-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;14. 慢查询优化思路 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p>四步走：</p><ol><li>用<strong>慢查询日志</strong> + <strong>EXPLAIN</strong> 定位问题 SQL；</li><li>看 <code>type</code> 是不是 <strong>ALL</strong>、<code>key</code> 是否为空，判断缺不缺索引；</li><li>加合适的索引：满足<strong>最左前缀</strong>、尽量做<strong>覆盖索引</strong>、避开索引失效场景；</li><li>再优化 SQL 本身：别 <code>SELECT *</code>、别在索引列上用函数、<strong>小表驱动大表</strong>。</li></ol><p>四步都做完还不行，才上<strong>读写分离</strong>、缓存、<strong>分库分表</strong>。原则是先看<strong>执行计划</strong>再动手，不要一上来就加缓存或分表。</p><hr><h2 id="_15-分库分表-★★☆" tabindex="-1">15. 分库分表 ★★☆ <a class="header-anchor" href="#_15-分库分表-★★☆" aria-label="Permalink to &quot;15. 分库分表 ★★☆&quot;">​</a></h2><p>两种拆法：</p><ul><li><strong>垂直拆</strong>：按业务拆库（订单库、用户库），或按列拆表（冷热字段分离）；</li><li><strong>水平拆</strong>：按行分，用 id 哈希或范围把数据分散到多表多库。</li></ul><p>中间件常用 <strong>ShardingSphere</strong>。分库分表会带来这些问题：<strong>分布式主键</strong>（雪花算法）、<strong>跨库 join</strong>、<strong>分布式事务</strong>、路由。</p><p>它是最后手段，优化顺序是「索引优化 → 缓存 → 读写分离 → 分库分表」；一般到<strong>单表千万级</strong>、单库出现瓶颈时才考虑。</p><hr><h2 id="_16-大表如何优化-★★★" tabindex="-1">16. 大表如何优化 ★★★ <a class="header-anchor" href="#_16-大表如何优化-★★★" aria-label="Permalink to &quot;16. 大表如何优化 ★★★&quot;">​</a></h2><p>从轻到重：</p><ul><li>索引优化，用<strong>覆盖索引</strong>避免<strong>回表</strong>；</li><li><strong>冷热数据分离</strong>，历史数据<strong>归档</strong>；</li><li><strong>读写分离</strong> + <strong>缓存热点</strong>；</li><li><strong>垂直 / 水平拆分</strong>；</li><li>最后才考虑列式存储 / 大数据引擎。</li></ul><p>典型做法是近期数据留在 MySQL（热），历史数据归档到冷库或 <strong>ClickHouse</strong>（冷），查询时路由到对应数据源，让<strong>主表</strong>一直保持较小。</p><hr><p><strong>补充（原文详解）</strong></p><p>当MySQL单表记录数过大时，数据库的CRUD性能会明显下降，一些常见的优化措施如下：</p><h3 id="_1-限定数据的范围" tabindex="-1">1. 限定数据的范围 <a class="header-anchor" href="#_1-限定数据的范围" aria-label="Permalink to &quot;1. 限定数据的范围&quot;">​</a></h3><p>务必禁止不带任何限制数据范围条件的查询语句。比如：我们当用户在查询订单历史的时候，我们可以控制在一个月的范围内；</p><h3 id="_2-读-写分离" tabindex="-1">2. 读/写分离 <a class="header-anchor" href="#_2-读-写分离" aria-label="Permalink to &quot;2. 读/写分离&quot;">​</a></h3><p>经典的数据库拆分方案，主库负责写，从库负责读；</p><h3 id="_3-垂直分区" tabindex="-1">3. 垂直分区 <a class="header-anchor" href="#_3-垂直分区" aria-label="Permalink to &quot;3. 垂直分区&quot;">​</a></h3><p>根据数据库里面数据表的相关性进行拆分。 例如，用户表中既有用户的登录信息又有用户的基本信息，可以将用户表拆分成两个单独的表，甚至放到单独的库做分库。</p><p>简单来说垂直拆分是指数据表列的拆分，把一张列比较多的表拆分为多张表。 如下图所示，这样来说大家应该就更容易理解了。</p><p>1583307481617</p><p>垂直拆分的优点： 可以使得列数据变小，在查询时减少读取的Block数，减少I/O次数。此外， 垂直分区可以简化表的结构，易于维护。</p><p>垂直拆分的缺点： 主键会出现冗余，需要管理冗余列，并会引起Join操作，可以通过在应用层进行Join来解决。此外，垂直分区会让事务变得更加复杂；</p><h3 id="_4-水平分区" tabindex="-1">4. 水平分区 <a class="header-anchor" href="#_4-水平分区" aria-label="Permalink to &quot;4. 水平分区&quot;">​</a></h3><p>保持数据表结构不变，通过某种策略存储数据分片。这样每一片数据分散到不同的表或者库中，达到了分布式的目的。 水平拆分可以支撑非常大的数据量。</p><p>水平拆分是指数据表行的拆分，表的行数超过200万行时，就会变慢，这时可以把一张的表的数据拆成多张表来存放。举个例子：我们可以将用户信息表拆分成多个用户信息表，这样就可以避免单一表数据量过大对性能造成影响。</p><p>1583308353521</p><p>水平拆分可以支持非常大的数据量。需要注意的一点是：分表仅仅是解决了单一表数据过大的问</p><p>题，但由于表的数据还是在同一台机器上，其实对于提升MySQL并发能力没有什么意义，所以水平拆分最好分库。</p><p>水平拆分能够支持非常大的数据量存储，应用端改造也少，但分片事务难以解决，跨节点Join性能较差，逻辑复杂。《Java工程师修炼之道》的作者推荐尽量不要对数据进行分片，因为拆分会带来逻辑、部署、运维的各种复杂度，一般的数据表在优化得当的情况下支撑千万以下的数据量是没有太大问题的。如果实在要分片，尽量选择客户端分片架构，这样可以减少一次和中间件的网络I/O。</p><p>下面补充一下数据库分片的两种常见方案：</p><p>客户端代理： 分片逻辑在应用端，封装在jar包中，通过修改或者封装JDBC层来实现。 当当网的 Sharding-JDBC、阿里的TDDL是两种比较常用的实现。</p><p>中间件代理： 在应用和数据中间加了一个代理层。分片逻辑统一维护在中间件服务中。 我们现在谈的 Mycat、360的Atlas、网易的DDB等等都是这种架构的实现。</p><p>详细内容可以参考： MySQL大表优化方案: <a href="https://segmentfault.com/a/1190000006158186" target="_blank" rel="noreferrer">https://segmentfault.com/a/1190000006158186</a></p><h2 id="_17-sql-执行顺序-★★☆" tabindex="-1">17. SQL 执行顺序 ★★☆ <a class="header-anchor" href="#_17-sql-执行顺序-★★☆" aria-label="Permalink to &quot;17. SQL 执行顺序 ★★☆&quot;">​</a></h2><p>执行顺序：<code>FROM</code> → <code>JOIN / ON</code> → <code>WHERE</code> → <code>GROUP BY</code> → <code>HAVING</code> → <code>SELECT</code> → <code>DISTINCT</code> → <code>ORDER BY</code> → <code>LIMIT</code>。</p><p>记住它才不会写错 SQL：</p><ul><li><strong>WHERE</strong> 在分组之前执行，所以不能用<strong>聚合函数</strong>，聚合条件必须写进 <strong>HAVING</strong>。</li><li><strong>SELECT</strong> 的<strong>别名</strong>在 WHERE 里不能用，因为 SELECT 比 WHERE 晚执行。</li><li>写统计 SQL 时，靠这个顺序判断条件该放 WHERE 还是 HAVING。</li></ul><hr><h2 id="_18-索引下推-icp-★★★" tabindex="-1">18. 索引下推（ICP）★★★ <a class="header-anchor" href="#_18-索引下推-icp-★★★" aria-label="Permalink to &quot;18. 索引下推（ICP）★★★&quot;">​</a></h2><p><strong>ICP</strong> 是 MySQL <strong>5.6</strong> 引入的优化：把「能在索引层判断的条件」下推到<strong>存储引擎层</strong>过滤，减少<strong>回表</strong>次数。</p><p>例子：<strong>联合索引</strong> (name, age) 查 <code>name like &#39;张%&#39; and age=20</code>。</p><ul><li>没有 ICP：先把所有 name 以「张」开头的记录<strong>回表</strong>，再在 <strong>Server 层</strong>过滤 age；</li><li>有 ICP：直接在索引层用 age 过滤，只有 name 和 age 都满足的记录才回表。</li></ul><p>限制：只对<strong>二级索引</strong>生效；条件里用了函数或运算就不会下推。这也解释了为什么「联合索引里带上<strong>过滤字段</strong>」能加速——可以在<strong>索引层</strong>就过滤掉大部分数据。</p><hr><h2 id="_19-索引设计原则-★★★" tabindex="-1">19. 索引设计原则 ★★★ <a class="header-anchor" href="#_19-索引设计原则-★★★" aria-label="Permalink to &quot;19. 索引设计原则 ★★★&quot;">​</a></h2><ul><li>选<strong>区分度高</strong>的列建索引；</li><li>为 WHERE、ORDER BY、GROUP BY、JOIN 涉及的列建索引；</li><li>联合索引按<strong>最左前缀</strong>设计，<strong>等值列在前</strong>、范围列在后；</li><li>尽量做成<strong>覆盖索引</strong>；</li><li>索引不能建太多，否则拖慢写入；</li><li>长字符串用<strong>前缀索引</strong>；</li><li>主键用<strong>自增</strong>。</li></ul><p><strong>区分度极低</strong>的列（性别、状态枚举）单独建索引没有意义，但可以作为联合索引里的过滤列。</p><hr><h2 id="_20-如何优化表结构-★★☆" tabindex="-1">20. 如何优化表结构 ★★☆ <a class="header-anchor" href="#_20-如何优化表结构-★★☆" aria-label="Permalink to &quot;20. 如何优化表结构 ★★☆&quot;">​</a></h2><ul><li>字段类型选够用的最小类型，能用 <strong>int</strong> 就不用 <strong>varchar</strong>，状态、类型用 <strong>tinyint</strong>；</li><li>尽量 <strong>NOT NULL</strong> 并给默认值；</li><li><strong>大字段</strong>（TEXT / BLOB，如报文原文）拆到<strong>扩展表</strong>，别撑大主表、拖慢查询；</li><li><strong>范式</strong>打底 + 适度反范式。</li></ul><hr><h2 id="_21-mysql-如何避免死锁-★★★" tabindex="-1">21. MySQL 如何避免死锁 ★★★ <a class="header-anchor" href="#_21-mysql-如何避免死锁-★★★" aria-label="Permalink to &quot;21. MySQL 如何避免死锁 ★★★&quot;">​</a></h2><p><strong>死锁</strong>是两个事务按不同顺序加锁、互相等待对方释放锁。避免手段：</p><ul><li>按<strong>固定顺序</strong>访问表和行；</li><li>用<strong>主键 / 唯一索引</strong>精确定位，缩小<strong>锁范围</strong>；</li><li>事务尽量小、尽快提交；</li><li>一次申请完所需的所有锁；</li><li>设置<strong>加锁超时</strong>，依赖<strong>死锁检测</strong>。</li></ul><p>发生死锁时 MySQL 会自动检测并回滚代价较小的那个事务，业务侧<strong>重试</strong>即可。排查用 <code>SHOW ENGINE INNODB STATUS</code> 的 <code>LATEST DETECTED DEADLOCK</code> 段。</p><hr><h2 id="_22-大量数据插入的性能优化-★★★" tabindex="-1">22. 大量数据插入的性能优化 ★★★ <a class="header-anchor" href="#_22-大量数据插入的性能优化-★★★" aria-label="Permalink to &quot;22. 大量数据插入的性能优化 ★★★&quot;">​</a></h2><p><strong>批量插</strong>（一条 INSERT 带多个 VALUES）比一条条插快很多，省的是<strong>网络往返</strong>、<strong>事务提交</strong>和 SQL 解析的开销。</p><p>进一步的手段：</p><ul><li><code>autocommit=0</code>，手动<strong>批量提交</strong>；</li><li>用 <code>LOAD DATA INFILE</code> 导入数据；</li><li>导入期间临时关闭唯一性 / 外键检查；</li><li>必要时先关索引，导完再重建索引。</li></ul><p>注意批次不是越大越好：批次太大就变成<strong>大事务</strong>，会长时间占锁、undo 膨胀、还可能拖慢<strong>主从复制</strong>。通常每 <strong>500~1000 条</strong>一批提交，兼顾速度和事务大小。</p><hr><h2 id="_23-大数据量批量写会导致什么问题-★★☆" tabindex="-1">23. 大数据量批量写会导致什么问题 ★★☆ <a class="header-anchor" href="#_23-大数据量批量写会导致什么问题-★★☆" aria-label="Permalink to &quot;23. 大数据量批量写会导致什么问题 ★★☆&quot;">​</a></h2><ul><li><strong>大事务</strong>：undo 膨胀、占锁久、造成<strong>主从延迟</strong>；</li><li><strong>锁竞争</strong>：批量更新<strong>锁范围</strong>大，容易<strong>死锁</strong>或长时间阻塞；</li><li><strong>binlog 膨胀</strong>；</li><li><strong>主从延迟</strong>；</li><li>随机主键插入还会<strong>页分裂</strong>。</li></ul><p>解决方式：<strong>分批提交</strong>、控制批次大小、用<strong>顺序主键</strong>、避开业务高峰；一次性更新几十万行最容易出问题。</p><hr><h2 id="_24-ip-地址如何存数据库-★★☆" tabindex="-1">24. IP 地址如何存数据库 ★★☆ <a class="header-anchor" href="#_24-ip-地址如何存数据库-★★☆" aria-label="Permalink to &quot;24. IP 地址如何存数据库 ★★☆&quot;">​</a></h2><ul><li><strong>IPv4</strong>：推荐用 <code>INT UNSIGNED</code> 存（<strong>4 字节</strong>），配 <code>INET_ATON()</code> / <code>INET_NTOA()</code> 互相转换。好处是<strong>省空间</strong>（比 varchar 短）、比较大小快、<strong>IP 段范围查询</strong>能走索引。</li><li><strong>IPv6</strong>：<strong>128 位</strong>，用 <code>VARBINARY(16)</code> 存，配 <code>INET6_ATON()</code> / <code>INET6_NTOA()</code> 转换。</li></ul><hr><h2 id="_25-drop、truncate、delete-的区别-★★★" tabindex="-1">25. drop、truncate、delete 的区别 ★★★ <a class="header-anchor" href="#_25-drop、truncate、delete-的区别-★★★" aria-label="Permalink to &quot;25. drop、truncate、delete 的区别 ★★★&quot;">​</a></h2><ul><li><strong>delete</strong> 是 <strong>DML</strong>，逐行删除、可带 WHERE、走 <strong>undo log</strong> 可回滚、会触发触发器，自增主键不重置，速度最慢。</li><li><strong>truncate</strong> 是 <strong>DDL</strong>，清空整张表、不能带 WHERE、<strong>隐式提交</strong>不可回滚、不触发触发器、自增值重置，本质是<strong>重建表</strong>（或直接释放数据页），速度快。</li><li><strong>drop</strong> 也是 DDL，直接删掉表结构和数据，连表定义都没了，速度最快。</li></ul><p>一句话：delete 删数据、truncate 清空表、drop 删表。</p><p>易错点：truncate 是 <strong>DDL</strong>、会<strong>隐式提交</strong>、不能回滚，误清数据救不回来。线上清理历史数据可以用 truncate 提效，但业务主表要走归档脚本分批 delete 或按<strong>分区清理</strong>。</p><hr><h2 id="_26-mysql-关联查询-join-类型及原理-★★★" tabindex="-1">26. MySQL 关联查询（JOIN 类型及原理）★★★ <a class="header-anchor" href="#_26-mysql-关联查询-join-类型及原理-★★★" aria-label="Permalink to &quot;26. MySQL 关联查询（JOIN 类型及原理）★★★&quot;">​</a></h2><p>JOIN 类型：</p><ul><li><strong>INNER JOIN</strong>：只保留两表都匹配的行；</li><li><strong>LEFT JOIN</strong>：左表全保留，右表没匹配的字段补 NULL；</li><li><strong>RIGHT JOIN</strong>：右表全保留，左表没匹配的字段补 NULL；</li><li><strong>FULL JOIN</strong>：MySQL 不支持，用 <code>LEFT JOIN UNION RIGHT JOIN</code> 模拟。</li></ul><p>执行原理是<strong>嵌套循环连接（Nested-Loop Join）</strong>：驱动表逐行到被驱动表找匹配。由此有两条铁律：</p><ol><li><strong>小表驱动大表</strong>，减少外层循环次数；</li><li>被驱动表的<strong>连接字段</strong>必须有索引，否则驱动表每行都要对被驱动表做一次<strong>全表扫描</strong>，复杂度 O(N*M)，直接爆炸。</li></ol><p>MySQL 8.0 还引入了 <strong>Hash Join</strong> 用于等值连接。JOIN 数量控制在两三个以内，再多的表改用冗余字段或拆成多次查询。</p><hr><h2 id="_27-分库分表之后-id-主键如何处理-雪花算法等分布式主键方案-★★★" tabindex="-1">27. 分库分表之后，id 主键如何处理（雪花算法等分布式主键方案）★★★ <a class="header-anchor" href="#_27-分库分表之后-id-主键如何处理-雪花算法等分布式主键方案-★★★" aria-label="Permalink to &quot;27. 分库分表之后，id 主键如何处理（雪花算法等分布式主键方案）★★★&quot;">​</a></h2><p>单表<strong>自增主键</strong>在分库分表后会重复，需要<strong>分布式主键</strong>。主流方案：</p><ul><li><strong>雪花算法（Snowflake）</strong>：64 位长整型，1 位符号 + <strong>41 位时间戳</strong>（约 69 年）+ 10 位机器 id + 12 位序列号。本地生成、趋势递增、全局唯一、性能高；缺点依赖机器时钟，<strong>时钟回拨</strong>可能生成重复 id。</li><li><strong>数据库号段模式</strong>（如美团 Leaf）：从一张表里批量取号段放内存，用完再取。严格有序，但多一次数据库依赖。</li><li><strong>Redis INCR</strong> 自增：简单，但依赖 Redis 的可用性。</li><li><strong>UUID</strong>：最简单，但无序，做主键会随机插入导致<strong>页分裂</strong>，且占空间，不推荐做主键。</li></ul><p>雪花算法应对<strong>时钟回拨</strong>：等待时钟追上、复用上次的序列号，或做校验兜底。</p><hr><h2 id="_28-一条查询-sql-的执行流程-连接器→分析器→优化器→执行器→存储引擎-★★★" tabindex="-1">28. 一条查询 SQL 的执行流程（连接器→分析器→优化器→执行器→存储引擎）★★★ <a class="header-anchor" href="#_28-一条查询-sql-的执行流程-连接器→分析器→优化器→执行器→存储引擎-★★★" aria-label="Permalink to &quot;28. 一条查询 SQL 的执行流程（连接器→分析器→优化器→执行器→存储引擎）★★★&quot;">​</a></h2><ol><li><strong>连接器</strong>：建立 TCP 连接，校验用户名密码和权限；<strong>长连接</strong>可复用，但连接数有限制。</li><li><strong>查询缓存</strong>：key 是 SQL 语句、value 是查询结果，命中直接返回。MySQL <strong>8.0</strong> 已整体移除该功能，8.0 之后不存在这一步。</li><li><strong>分析器</strong>：做<strong>词法分析</strong>和<strong>语法分析</strong>，识别关键字、表名、列名并生成解析树；语法错误在这一层报出。</li><li><strong>优化器</strong>：决定用哪个索引、多表 join 的连接顺序，生成<strong>执行计划</strong>（也可能选错索引）。</li><li><strong>执行器</strong>：校验权限后调用存储引擎接口，逐行取数据、过滤，返回客户端。</li><li><strong>存储引擎 InnoDB</strong>：负责真正的数据读写，走 <strong>buffer pool</strong>、索引和回表。</li></ol>',98)),(n(),a(l,null,{default:r(()=>[e(s,{id:"mermaid-1108",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E8%BF%9E%E6%8E%A5%E5%99%A8%3Cbr%2F%3E%E5%BB%BA%E8%BF%9E%E6%8E%A5%C2%B7%E9%89%B4%E6%9D%83%5D%20--%3E%20B%5B%E5%88%86%E6%9E%90%E5%99%A8%3Cbr%2F%3E%E8%AF%8D%E6%B3%95%C2%B7%E8%AF%AD%E6%B3%95%E5%88%86%E6%9E%90%5D%0A%20%20%20%20B%20--%3E%20C%5B%E4%BC%98%E5%8C%96%E5%99%A8%3Cbr%2F%3E%E9%80%89%E7%B4%A2%E5%BC%95%C2%B7%E5%AE%9A%E6%89%A7%E8%A1%8C%E8%AE%A1%E5%88%92%5D%0A%20%20%20%20C%20--%3E%20D%5B%E6%89%A7%E8%A1%8C%E5%99%A8%3Cbr%2F%3E%E8%B0%83%E5%BC%95%E6%93%8E%E6%8E%A5%E5%8F%A3%E5%8F%96%E6%95%B0%5D%0A%20%20%20%20D%20--%3E%20E%5B%E5%AD%98%E5%82%A8%E5%BC%95%E6%93%8E%20InnoDB%3Cbr%2F%3Ebuffer%20pool%C2%B7%E7%B4%A2%E5%BC%95%C2%B7%E5%9B%9E%E8%A1%A8%5D%0A"})]),fallback:r(()=>o[1]||(o[1]=[i(" Loading... ")])),_:1})),o[4]||(o[4]=t('<p>由此可以解释两类现象：连接数打满报 <code>too many connections</code>，属于<strong>连接器 / 连接池</strong>层的问题；EXPLAIN 显示走了不该走的索引，是<strong>优化器</strong>基于过期统计信息选错，可用 <code>force index</code> 或 <code>analyze table</code> 更新<strong>统计信息</strong>纠正。</p><hr><h2 id="_29-ddl-dml-dcl-dql-的区别-★★☆" tabindex="-1">29. DDL / DML / DCL / DQL 的区别 ★★☆ <a class="header-anchor" href="#_29-ddl-dml-dcl-dql-的区别-★★☆" aria-label="Permalink to &quot;29. DDL / DML / DCL / DQL 的区别 ★★☆&quot;">​</a></h2><ul><li><strong>DDL</strong>（数据定义语言）：操作表结构，CREATE、DROP、ALTER、TRUNCATE，会<strong>隐式提交</strong>、不可回滚。</li><li><strong>DML</strong>（数据操纵语言）：操作数据，INSERT、UPDATE、DELETE，可回滚。</li><li><strong>DCL</strong>（数据控制语言）：管理权限，GRANT、REVOKE。</li><li><strong>DQL</strong>（数据查询语言）：SELECT。</li></ul><p>常考易错点：<strong>truncate</strong> 归 <strong>DDL</strong> 而不归 DML，所以它不能回滚、不触发触发器，这正是它与 <strong>delete</strong> 本质区别的来源。</p><p>生产上 DDL 要格外小心：大表 <strong>alter</strong> 会<strong>锁表</strong>或整表重建，需要专门的上线窗口，必要时用在线变更工具；DML 批量写走<strong>分批提交</strong>。</p><hr><h2 id="_30-存储过程和触发器的作用及优缺点-★★☆" tabindex="-1">30. 存储过程和触发器的作用及优缺点 ★★☆ <a class="header-anchor" href="#_30-存储过程和触发器的作用及优缺点-★★☆" aria-label="Permalink to &quot;30. 存储过程和触发器的作用及优缺点 ★★☆&quot;">​</a></h2><p><strong>存储过程</strong>是把一段 SQL 逻辑<strong>预编译</strong>后存到数据库里，可以传参调用。</p><ul><li>优点：减少网络往返、复用逻辑、权限可控。</li><li>缺点：难调试、难维护、难版本化、跨库迁移麻烦，逻辑藏在数据库里不好排查。</li></ul><p><strong>触发器</strong>是绑定在表上、在 INSERT / UPDATE / DELETE 前后自动执行的逻辑，常用于审计、数据校验、同步。</p><ul><li>缺点：逻辑隐蔽、<strong>逐行触发</strong>影响写入性能、出问题难定位。</li></ul><p>互联网项目普遍把逻辑放<strong>应用层</strong>（可版本管理、可单测、可灰度），少用或不用存储过程和触发器。</p><hr><h2 id="_31-mysql-如何行转列和列转行-case-when、group-concat、union-★★☆" tabindex="-1">31. MySQL 如何行转列和列转行（CASE WHEN、GROUP_CONCAT、UNION）★★☆ <a class="header-anchor" href="#_31-mysql-如何行转列和列转行-case-when、group-concat、union-★★☆" aria-label="Permalink to &quot;31. MySQL 如何行转列和列转行（CASE WHEN、GROUP_CONCAT、UNION）★★☆&quot;">​</a></h2><ul><li><strong>行转列</strong>：把同一维度下的多行变成多列。用 <strong>CASE WHEN</strong>（或 IF）做条件判断，外面套<strong>聚合函数</strong> SUM / MAX，再配合 <strong>GROUP BY</strong> 分组。例：统计每个场站待支付、充电中、已完成三类订单数，就是按 status 做 CASE WHEN 再 SUM。</li><li><strong>列转行</strong>：把多列拆成多行，用 <strong>UNION ALL</strong> 把每列分别 SELECT 出来拼在一起。</li><li><strong>GROUP_CONCAT</strong>：把多行合成一行里的一个字符串列，可指定分隔符；默认<strong>长度有限制</strong>，受 <code>group_concat_max_len</code> 控制。</li></ul><hr><h2 id="_32-union-和-union-all-的区别-★★★" tabindex="-1">32. UNION 和 UNION ALL 的区别 ★★★ <a class="header-anchor" href="#_32-union-和-union-all-的区别-★★★" aria-label="Permalink to &quot;32. UNION 和 UNION ALL 的区别 ★★★&quot;">​</a></h2><ul><li><strong>UNION</strong>：合并两个结果集并<strong>去重</strong>，内部要对合并结果做<strong>排序去重</strong>，有额外开销，慢。</li><li><strong>UNION ALL</strong>：直接拼接、不去重，快。</li></ul><p>两者都要求两个 SELECT 的<strong>列数、类型、顺序</strong>一致。</p><p>规则：能确定结果无重复、或本来就允许重复时，一律用 <strong>UNION ALL</strong>，不要白花去重排序的代价。例如把热数据（MySQL 主表）和冷数据（归档）合并成完整列表时，两边天然不重复，用 UNION 反而多一次去重排序拖慢接口。</p><hr><h2 id="_33-having-和-where-的区别-★★★" tabindex="-1">33. HAVING 和 WHERE 的区别 ★★★ <a class="header-anchor" href="#_33-having-和-where-的区别-★★★" aria-label="Permalink to &quot;33. HAVING 和 WHERE 的区别 ★★★&quot;">​</a></h2><ul><li><strong>WHERE</strong> 在分组（<strong>GROUP BY</strong>）之前过滤行，不能用<strong>聚合函数</strong>，也不能用 SELECT 的<strong>别名</strong>。</li><li><strong>HAVING</strong> 在分组之后过滤分组，可以使用聚合函数。</li></ul><p>执行顺序：WHERE → GROUP BY → HAVING → SELECT。</p><p>性能原则：能放 WHERE 的就放 WHERE，先把数据量过滤小再分组；HAVING 只处理必须基于<strong>聚合结果</strong>的条件（如 <code>COUNT(*) &amp;gt; 10</code>）。例如查订单数超过 10 的场站，场站状态这种<strong>行级条件</strong>放 WHERE，<code>COUNT(*) &amp;gt; 10</code> 只能放 HAVING。</p><hr><h2 id="_34-in-和-exists-子句的区别及选择-★★★" tabindex="-1">34. IN 和 EXISTS 子句的区别及选择 ★★★ <a class="header-anchor" href="#_34-in-和-exists-子句的区别及选择-★★★" aria-label="Permalink to &quot;34. IN 和 EXISTS 子句的区别及选择 ★★★&quot;">​</a></h2><ul><li><strong>IN</strong>：先执行<strong>子查询</strong>拿到结果集，再和外层逐行做集合匹配。适合子查询结果集小、外层表大的场景。</li><li><strong>EXISTS</strong>：外层每行去子查询探测是否存在，找到一个匹配就返回 true、可提前终止，不加载整个结果集。适合外层表小、子查询大、且子查询能走索引的场景。</li></ul><p>最大的坑：<strong>NOT IN</strong> 的子查询结果里只要有 <strong>NULL</strong>，整个结果就会变成空——NULL 参与比较结果为 unknown，所有行都被过滤；<strong>NOT EXISTS</strong> 没有这个问题。所以否定判断优先用 <strong>NOT EXISTS</strong>，排查「明明有数据却查不出来」时也要先想到它。</p><p>选择原则：子查询小用 IN、外层小用 EXISTS。</p><hr><h2 id="_35-mysql-如何处理-null-值-对索引-查询的影响-★★★" tabindex="-1">35. MySQL 如何处理 NULL 值，对索引/查询的影响 ★★★ <a class="header-anchor" href="#_35-mysql-如何处理-null-值-对索引-查询的影响-★★★" aria-label="Permalink to &quot;35. MySQL 如何处理 NULL 值，对索引/查询的影响 ★★★&quot;">​</a></h2><p><strong>NULL</strong> 表示「未知 / 缺失」，它不等于任何值、包括它自己：<code>NULL = NULL</code> 的结果是 NULL 而不是 true，判断必须用 <strong>IS NULL</strong> / <strong>IS NOT NULL</strong>。</p><p>对聚合的影响：</p><ul><li><strong>COUNT(列)</strong> 会忽略 NULL 行，<code>COUNT(*)</code> 才统计全部行；</li><li>SUM / AVG 也会忽略 NULL。</li></ul><p>对索引的影响：</p><ul><li><strong>唯一索引</strong>允许插入多个 NULL，因为 NULL 之间被认为不相等；</li><li>普通索引可以存 NULL，<code>IS NULL</code> 一般能走索引。</li></ul><p>常见坑：<strong>NOT IN</strong> 子查询含 NULL 导致结果为空；字段可空时用 <code>=</code> 判断查不到 NULL 行；COUNT 的统计口径也容易混乱。因此建表尽量 <strong>NOT NULL</strong> 并给默认值，可空字段（如结束时间、退款时间）查询时用 <strong>IS NULL</strong> 而不是 <code>= NULL</code>。</p><hr><h2 id="_36-如何在-mysql-中处理和避免全表扫描-★★★" tabindex="-1">36. 如何在 MySQL 中处理和避免全表扫描 ★★★ <a class="header-anchor" href="#_36-如何在-mysql-中处理和避免全表扫描-★★★" aria-label="Permalink to &quot;36. 如何在 MySQL 中处理和避免全表扫描 ★★★&quot;">​</a></h2><p><strong>全表扫描</strong>就是 EXPLAIN 里 <strong>type=ALL</strong>，逐行读整张表的所有数据页，数据量大时必然慢。</p><p>避免手段：</p><ol><li>建对索引并确保走索引：满足<strong>最左前缀</strong>，避开索引列上用函数、隐式类型转换等失效场景；</li><li>避免 <code>SELECT *</code>，只取需要的列，尽量用<strong>覆盖索引</strong>；</li><li>用 WHERE 有效缩小范围，避免无过滤条件或低区分度的单列条件；</li><li>JOIN 时<strong>小表驱动大表</strong>，被驱动表连接字段建索引；</li><li><strong>深分页</strong>优化：大 <strong>OFFSET</strong> 会扫大量行，改用「先查主键再回表」的<strong>延迟关联</strong>或<strong>游标分页</strong>；</li><li>冷热分离、历史归档，让主表一直保持小，从根上降低全表扫描的代价。</li></ol><p>最终用 <strong>EXPLAIN</strong> 确认 type 不是 ALL。例如订单列表变慢就是 type=ALL，加<strong>联合索引</strong>后降到 <strong>range</strong>；深分页用先按主键查一页 id 再回表，避免扫几万行。</p><hr><h2 id="_37-数据库的三范式是什么" tabindex="-1">37. 数据库的三范式是什么 <a class="header-anchor" href="#_37-数据库的三范式是什么" aria-label="Permalink to &quot;37. 数据库的三范式是什么&quot;">​</a></h2><p>第一范式：列不可再分第二范式：行可以唯一区分，主键约束第三范式：表的非主属性不能依赖与其他表的非主属性外键约束且三大范式是一级一级依赖的，第二范式建立在第一范式上，第三范式建立第一第二范式上。</p><h2 id="_38-mysql数据库引擎有哪些" tabindex="-1">38. MySQL数据库引擎有哪些 <a class="header-anchor" href="#_38-mysql数据库引擎有哪些" aria-label="Permalink to &quot;38. MySQL数据库引擎有哪些&quot;">​</a></h2><p>如何查看mysql提供的所有存储引擎</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">mysql</span><span style="color:#F97583;">&gt;</span><span style="color:#E1E4E8;"> show engines;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">mysql</span><span style="color:#D73A49;">&gt;</span><span style="color:#24292E;"> show engines;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+c+'" alt="img"></p><p>mysql常用引擎包括：MYISAM、 Innodb、 Memory、 MERGE</p><p>MYISAM：全表锁，拥有较高的执行速度，不支持事务，不支持外键，并发性能差，占用空间相对较小，对事务完整性没有要求，以select、 insert为主的应用基本上可以使用这引擎</p><p>Innodb:行级锁，提供了具有提交、回滚和崩溃回复能力的事务安全，支持自动增长列，支持外键约束，并发能力强，占用空间是MYISAM的2.5倍，处理效率相对会差一些</p><p>Memory:全表锁，存储在内容中，速度快，但会占用和数据量成正比的内存空间且数据在</p><p>mysql重启时会丢失，默认使用HASH索引，检索效率非常高，但不适用于精确查找，主要用于那些内容变化不频繁的代码表</p><p>MERGE：是一组MYISAM表的组合</p><h2 id="_39-数据库的事务" tabindex="-1">39. 数据库的事务 <a class="header-anchor" href="#_39-数据库的事务" aria-label="Permalink to &quot;39. 数据库的事务&quot;">​</a></h2><p>什么是事务？： 多条sql语句，要么全部成功，要么全部失败。</p><p>事务的特性：</p><p>数据库事务特性：原子性(Atomic)、一致性(Consistency)、隔离性(Isolation)、持久性 (Durabiliy)。简称ACID。</p><p>原子性：组成一个事务的多个数据库操作是一个不可分割的原子单元，只有所有操作都成功， 整个事务才会提交。任何一个操作失败，已经执行的任何操作都必须撤销，让数据库返回初始状态。</p><p>一致性：事务操作成功后，数据库所处的状态和它的业务规则是一致的。即数据不会被破坏。 如A转账100元给B，不管操作是否成功，A和B的账户总额是不变的。</p><p>隔离性：在并发数据操作时，不同的事务拥有各自的数据空间，它们的操作不会对彼此产生干扰</p><p>持久性：一旦事务提交成功，事务中的所有操作都必须持久化到数据库中。</p><h2 id="_40-索引是什么" tabindex="-1">40. 索引是什么 <a class="header-anchor" href="#_40-索引是什么" aria-label="Permalink to &quot;40. 索引是什么&quot;">​</a></h2><p>官方介绍索引是帮助MySQL高效获取数据的数据结构。更通俗的说，数据库索引好比是一本书前面的目录，能加快数据库的查询速度。</p><p>一般来说索引本身也很大，不可能全部存储在内存中，因此索引往往是存储在磁盘上的文件中的（可能存储在单独的索引文件中，也可能和数据一起存储在数据文件中）。</p><p>我们通常所说的索引，包括聚集索引、覆盖索引、组合索引、前缀索引、唯一索引等，没有特别说明，默认都是使用B+树结构组织（多路搜索树，并不一定是二叉的）的索引。</p><h2 id="_41-sql优化手段有哪些" tabindex="-1">41. SQL优化手段有哪些 <a class="header-anchor" href="#_41-sql优化手段有哪些" aria-label="Permalink to &quot;41. SQL优化手段有哪些&quot;">​</a></h2><p>1、查询语句中不要使用select *</p><p>2、尽量减少子查询，使用关联查询（left join,right join,inner join）替代</p><p>3、减少使用IN或者NOT IN ,使用exists，not exists或者关联查询语句替代</p><p>4、or 的查询尽量用 union或者union all 代替(在确认没有重复数据或者不用剔除重复数据时， union all会更好)</p><p>5、应尽量避免在 where 子句中使用!=或&lt;&gt;操作符，否则将引擎放弃使用索引而进行全表扫描。</p><p>6、应尽量避免在 where 子句中对字段进行 null 值判断，否则将导致引擎放弃使用索引而进行全表扫描，如： select id from t where num is null 可以在num上设置默认值0，确保表中num列没有 null值，然后这样查询： select id from t where num=0</p><h2 id="_42-什么是视图" tabindex="-1">42. 什么是视图 <a class="header-anchor" href="#_42-什么是视图" aria-label="Permalink to &quot;42. 什么是视图&quot;">​</a></h2><p>视图是一种虚拟的表，具有和物理表相同的功能。可以对视图进行增，改，查，操作，试图通常是有一个表或者多个表的行或列的子集。对视图的修改不影响基本表。它使得我们获取数据更容易， 相比多表查询。</p><h2 id="_43-什么是内联接、左外联接、右外联接" tabindex="-1">43. 什么是内联接、左外联接、右外联接？ <a class="header-anchor" href="#_43-什么是内联接、左外联接、右外联接" aria-label="Permalink to &quot;43. 什么是内联接、左外联接、右外联接？&quot;">​</a></h2><p>内联接（Inner Join）：匹配2张表中相关联的记录。</p><p>左外联接（Left Outer Join）：除了匹配2张表中相关联的记录外，还会匹配左表中剩余的记录，右表中未匹配到的字段用NULL表示。</p><p>右外联接（Right Outer Join）：除了匹配2张表中相关联的记录外，还会匹配右表中剩余的记录，左表中未匹配到的字段用NULL表示。在判定左表和右表时，要根据表名出现在Outer Join 的左右位置关系。</p><h2 id="_44-并发事务带来哪些问题" tabindex="-1">44. 并发事务带来哪些问题? <a class="header-anchor" href="#_44-并发事务带来哪些问题" aria-label="Permalink to &quot;44. 并发事务带来哪些问题?&quot;">​</a></h2><p>在典型的应用程序中，多个事务并发运行，经常会操作相同的数据来完成各自的任务（多个用户对同一数据进行操作）。并发虽然是必须的，但可能会导致以下的问题。</p><p>脏读（Dirty read）: 当一个事务正在访问数据并且对数据进行了修改，而这种修改还没有提交到数据库中，这时另外一个事务也访问了这个数据，然后使用了这个数据。因为这个数据是还没有提交的数据，那么另外一个事务读到的这个数据是“脏数据”，依据“脏数据”所做的操作可能是不正确的。</p><p>丢失修改（Lost to modify）: 指在一个事务读取一个数据时，另外一个事务也访问了该数</p><p>据，那么在第一个事务中修改了这个数据后，第二个事务也修改了这个数据。这样第一个事务内的修改结果就被丢失，因此称为丢失修改。 例如：事务1读取某表中的数据A=20，事务2也读取A=20，事务1修改A=A-1，事务2也修改A=A-1，最终结果A=19，事务1的修改被丢失。</p><p>不可重复读（Unrepeatableread）: 指在一个事务内多次读同一数据。在这个事务还没有结束时，另一个事务也访问该数据。那么，在第一个事务中的两次读数据之间，由于第二个事务的修改导致第一个事务两次读取的数据可能不太一样。这就发生了在一个事务内两次读到的数据是不一样的情况，因此称为不可重复读。</p><p>幻读（Phantom read）: 幻读与不可重复读类似。它发生在一个事务（T1）读取了几行数</p><p>据，接着另一个并发事务（T2）插入了一些数据时。在随后的查询中，第一个事务（T1）就会发现多了一些原本不存在的记录，就好像发生了幻觉一样，所以称为幻读。</p><p>不可重复读和幻读区别：</p><p>不可重复读的重点是修改比如多次读取一条记录发现其中某些列的值被修改，幻读的重点在于新增或者删除比如多次读取一条记录发现记录增多或减少了。</p><h2 id="_45-分库分表之后-id-主键如何处理" tabindex="-1">45. 分库分表之后,id 主键如何处理？ <a class="header-anchor" href="#_45-分库分表之后-id-主键如何处理" aria-label="Permalink to &quot;45. 分库分表之后,id 主键如何处理？&quot;">​</a></h2><p>因为要是分成多个表之后，每个表都是从 1 开始累加，这样是不对的，我们需要一个全局唯一的 id 来支持。</p><p>生成全局 id 有下面这几种方式：</p><p>UUID：不适合作为主键，因为太长了，并且无序不可读，查询效率低。比较适合用于生成唯</p><p>一的名字的标示比如文件的名字。</p><p>数据库自增 id : 两台数据库分别设置不同步长，生成不重复ID的策略来实现高可用。这种方式生成的 id 有序，但是需要独立部署数据库实例，成本高，还会有性能瓶颈。</p><p>利用 redis 生成 id :性能比较好，灵活方便，不依赖于数据库。但是，引入了新的组件造成系统更加复杂，可用性降低，编码更加复杂，增加了系统成本。</p><p>Twitter的snowﬂake算法：Github 地址： <a href="https://github.com/twitter-archive/snow%EF%AC%82ake%E3%80%82" target="_blank" rel="noreferrer">https://github.com/twitter-archive/snowﬂake。</a> 美团的Leaf分布式ID生成系统：Leaf 是美团开源的分布式ID生成器，能保证全局唯一性、趋</p><p>势递增、单调递增、信息安全，里面也提到了几种分布式方案的对比，但也需要依赖关系数据库、 Zookeeper等中间件。感觉还不错。美团技术团队的一篇文章： <a href="https://tech.meituan.co" target="_blank" rel="noreferrer">https://tech.meituan.co</a> m/2017/04/21/mt-leaf.html。</p><h2 id="_46-说说在-mysql-中一条查询-sql-是如何执行的" tabindex="-1">46. 说说在 MySQL 中一条查询 SQL 是如何执行的？ <a class="header-anchor" href="#_46-说说在-mysql-中一条查询-sql-是如何执行的" aria-label="Permalink to &quot;46. 说说在 MySQL 中一条查询 SQL 是如何执行的？&quot;">​</a></h2><p>比如下面这条SQL语句：</p><p>select name from t_user where id=1</p><ol><li><p>取得链接，使用使用到 MySQL 中的连接器。</p></li><li><p>查询缓存 ，key 为 SQL 语句，value 为查询结果，如果查到就直接返回。不建议使用次缓存， 在 MySQL 8.0 版本已经将查询缓存删除，也就是说 MySQL 8.0 版本后不存在此功能。</p></li><li><p>分析器，分为词法分析和语法分析。此阶段只是做一些 SQL 解析，语法校验。所以一般语法错 误在此阶段。</p></li><li><p>优化器，是在表里有多个索引的时候，决定使用哪个索引；或者一个语句中存在多表关联的时 候（join），决定各个表的连接顺序。</p></li><li><p>执行器，通过分析器让 SQL 知道你要干啥，通过优化器知道该怎么做，于是开始执行语句。执 行语句的时候还要判断是否具备此权限，没有权限就直接返回提示没有权限的错误；有权限则 打开表，根据表的引擎定义，去使用这个引擎提供的接口，获取这个表的第一行，判断 id 是都</p></li></ol><p>等于 1。如果是，直接返回；如果不是继续调用引擎接口去下一行，重复相同的判断，直到取到这个表的最后一行，最后返回。</p><h2 id="_47-索引有什么优缺点" tabindex="-1">47. 索引有什么优缺点？ <a class="header-anchor" href="#_47-索引有什么优缺点" aria-label="Permalink to &quot;47. 索引有什么优缺点？&quot;">​</a></h2><p><img src="'+h+'" alt="img"></p><h2 id="_48-mysql-中-varchar-与-char-的区别-varchar-30-中的-30-代表的涵义" tabindex="-1">48. MySQL 中 varchar 与 char 的区别？ varchar(30) 中的 30 代表的涵义？ <a class="header-anchor" href="#_48-mysql-中-varchar-与-char-的区别-varchar-30-中的-30-代表的涵义" aria-label="Permalink to &quot;48. MySQL 中 varchar 与 char 的区别？ varchar(30) 中的 30 代表的涵义？&quot;">​</a></h2><p>varchar 与 char 的区别，char 是一种固定长度的类型， varchar 则是一种可变长度的类型。</p><p>varchar(30) 中 30 的涵义最多存放 30 个字符。 varchar(30) 和 (130) 存储 hello 所占空间一样，但后者在排序时会消耗更多内存，因为 ORDER BY col 采用 ﬁxed_length 计算 col 长度 （ memory 引擎也一样）。</p><p>对效率要求高用 char，对空间使用要求高用 varchar。</p><h2 id="_49-int-11-中的-11-代表什么涵义" tabindex="-1">49. int(11) 中的 11 代表什么涵义？ <a class="header-anchor" href="#_49-int-11-中的-11-代表什么涵义" aria-label="Permalink to &quot;49. int(11) 中的 11 代表什么涵义？&quot;">​</a></h2><p>int(11) 中的 11，不影响字段存储的范围，只影响展示效果。</p><h2 id="_50-为什么-select-count-from-table-在-innodb-比-myisam-慢" tabindex="-1">50. 为什么 SELECT COUNT(*) FROM table 在 InnoDB 比 MyISAM 慢？ <a class="header-anchor" href="#_50-为什么-select-count-from-table-在-innodb-比-myisam-慢" aria-label="Permalink to &quot;50. 为什么 SELECT COUNT(*) FROM table 在 InnoDB 比 MyISAM 慢？&quot;">​</a></h2><p>对于 SELECT COUNT(*) FROM table 语句，在没有 WHERE 条件的情况下，InnoDB 比 MyISAM 可</p><p>能会慢很多，尤其在大表的情况下。因为，InnoDB 是去实时统计结果，会全表扫描；而 MyISAM 内部维持了一个计数器，预存了结果，所以直接返回即可。</p><h2 id="_51-mysql-索引类型有哪些" tabindex="-1">51. MySQL 索引类型有哪些？ <a class="header-anchor" href="#_51-mysql-索引类型有哪些" aria-label="Permalink to &quot;51. MySQL 索引类型有哪些？&quot;">​</a></h2><p>主键索引</p><p>索引列中的值必须是唯一的，不允许有空值。</p><p>普通索引</p><p>MySQL中基本索引类型，没有什么限制，允许在定义索引的列中插入重复值和空值。</p><p>唯一索引</p><p>索引列中的值必须是唯一的，但是允许为空值。</p><p>全文索引</p><p>只能在文本类型CHAR,VARCHAR,TEXT类型字段上创建全文索引。字段长度比较大时，如果创建普通索引，在进行like模糊查询时效率比较低，这时可以创建全文索引。 MyISAM和InnoDB中都可以使用全文索引。</p><p>空间索引</p><p>MySQL在5.7之后的版本支持了空间索引，而且支持OpenGIS几何数据模型。 MySQL在空间索引这方面遵循OpenGIS几何数据模型规则。</p><p>前缀索引</p><p>在文本类型如CHAR,VARCHAR,TEXT类列上创建索引时，可以指定索引列的长度，但是数值类型不能指定。</p><p>其他（按照索引列数量分类）</p><ol><li><p>单列索引</p></li><li><p>组合索引</p></li></ol><p>组合索引的使用，需要遵循最左前缀匹配原则（最左匹配原则）。一般情况下在条件允许的情况下使用组合索引替代多个单列索引使用。</p><h2 id="_52-什么时候不要使用索引" tabindex="-1">52. 什么时候不要使用索引？ <a class="header-anchor" href="#_52-什么时候不要使用索引" aria-label="Permalink to &quot;52. 什么时候不要使用索引？&quot;">​</a></h2><ol><li><p>经常增删改的列不要建立索引；</p></li><li><p>有大量重复的列不建立索引；</p></li><li><p>表记录太少不要建立索引。</p></li></ol><h2 id="_53-说说什么是-mvcc" tabindex="-1">53. 说说什么是 MVCC？ <a class="header-anchor" href="#_53-说说什么是-mvcc" aria-label="Permalink to &quot;53. 说说什么是 MVCC？&quot;">​</a></h2><p>多版本并发控制（MVCC=Multi-Version Concurrency Control），是一种用来解决读 - 写冲突的无锁并发控制。也就是为事务分配单向增长的时间戳，为每个修改保存一个版本。版本与事务时间戳关联，读操作只读该事务开始前的数据库的快照（复制了一份数据）。这样在读操作不用阻塞写操作，写操作不用阻塞读操作的同时，避免了脏读和不可重复读。</p><h2 id="_54-mvcc-可以为数据库解决什么问题" tabindex="-1">54. MVCC 可以为数据库解决什么问题？ <a class="header-anchor" href="#_54-mvcc-可以为数据库解决什么问题" aria-label="Permalink to &quot;54. MVCC 可以为数据库解决什么问题？&quot;">​</a></h2><p>在并发读写数据库时，可以做到在读操作时不用阻塞写操作，写操作也不用阻塞读操作，提高了数据库并发读写的性能。同时还可以解决脏读、幻读、不可重复读等事务隔离问题，但不能解决更新丢失问题。</p><h2 id="_55-说说-mvcc-的实现原理" tabindex="-1">55. 说说 MVCC 的实现原理 <a class="header-anchor" href="#_55-说说-mvcc-的实现原理" aria-label="Permalink to &quot;55. 说说 MVCC 的实现原理&quot;">​</a></h2><p>MVCC 的目的就是多版本并发控制，在数据库中的实现，就是为了解决读写冲突，它的实现原理主要是依赖记录中的 3 个隐式字段、undo 日志、 Read View 来实现的。</p><h2 id="_56-请说说-mysql-数据库的锁" tabindex="-1">56. 请说说 MySQL 数据库的锁？ <a class="header-anchor" href="#_56-请说说-mysql-数据库的锁" aria-label="Permalink to &quot;56. 请说说 MySQL 数据库的锁？&quot;">​</a></h2><p>关于 MySQL 的锁机制，可能会问很多问题，不过这也得看面试官在这方面的知识储备。</p><p>MySQL 中有共享锁和排它锁，也就是读锁和写锁。</p><ol><li><p>共享锁：不堵塞，多个用户可以同一时刻读取同一个资源，相互之间没有影响。</p></li><li><p>排它锁：一个写操作阻塞其他的读锁和写锁，这样可以只允许一个用户进行写入，防止其他用 户读取正在写入的资源。</p></li><li><p>表锁：系统开销最小，会锁定整张表，MyISAM 使用表锁。</p></li><li><p>行锁：容易出现死锁，发生冲突概率低，并发高，InnoDB 支持行锁（必须有索引才能实现， 否则会自动锁全表，那么就不是行锁了）。</p></li></ol><h2 id="_57-说说什么是锁升级" tabindex="-1">57. 说说什么是锁升级？ <a class="header-anchor" href="#_57-说说什么是锁升级" aria-label="Permalink to &quot;57. 说说什么是锁升级？&quot;">​</a></h2><p>MySQL 行锁只能加在索引上，如果操作不走索引，就会升级为表锁。因为 InnoDB 的行锁是加在索引上的，如果不走索引，自然就没法使用行锁了，原因是 InnoDB 是将 primary key index 和相关的行数据共同放在 B+ 树的叶节点。 InnoDB 一定会有一个 primary key，secondary</p><p>index 查找的时候，也是通过找到对应的 primary，再找对应的数据行。</p><p>当非唯一索引上记录数超过一定数量时，行锁也会升级为表锁。测试发现当非唯一索引相同的内容不少于整个表记录的二分之一时会升级为表锁。因为当非唯一索引相同的内容达到整个记录的二分之一时，索引需要的性能比全文检索还要大，查询语句优化时会选择不走索引，造成索引失效，行锁自然就会升级为表锁。</p><h2 id="_58-说说悲观锁和乐观锁" tabindex="-1">58. 说说悲观锁和乐观锁 <a class="header-anchor" href="#_58-说说悲观锁和乐观锁" aria-label="Permalink to &quot;58. 说说悲观锁和乐观锁&quot;">​</a></h2><p>悲观锁</p><p>说的是数据库被外界（包括本系统当前的其他事物以及来自外部系统的事务处理）修改保持着保守态度，因此在整个数据修改过程中，将数据处于锁状态。悲观的实现往往是依靠数据库提供的锁机制，也只有数据库层面提供的锁机制才能真正保证数据访问的排他性，否则，即使在本系统汇总实现了加锁机制，也是没有办法保证系统不会修改数据。</p><p>在悲观锁的情况下，为了保证事务的隔离性，就需要一致性锁定读。读取数据时给加锁，其它事务无法修改这些数据。修改删除数据时也要加锁，其它事务无法读取这些数据。</p><p>乐观锁</p><p>相对悲观锁而言，乐观锁机制采取了更加宽松的加锁机制。悲观锁大多数情况下依靠数据库的锁机制实现，以保证操作最大程度的独占性。但随之而来的就是数据库性能的大量开销，特别是对长事务而言，这样的开销往往无法承受。</p><p>而乐观锁机制在一定程度上解决了这个问题。乐观锁，大多是基于数据版本（Version）记录机制实现。何谓数据版本？即为数据增加一个版本标识，在基于数据库表的版本解决方案中，一般是通过为数据库表增加一个“version”字段来实现。读取出数据时，将此版本号一同读出，之后更新时，对此版本号加一。此时，将提交数据的版本数据与数据库表对应记录的当前版本信息进行比对，如果提交的数据版本号大于数据库表当前版本号，则予以更新，否则认为是过期数据。</p><h2 id="_59-怎样尽量避免死锁的出现" tabindex="-1">59. 怎样尽量避免死锁的出现？ <a class="header-anchor" href="#_59-怎样尽量避免死锁的出现" aria-label="Permalink to &quot;59. 怎样尽量避免死锁的出现？&quot;">​</a></h2><ol><li><p>设置获取锁的超时时间，至少能保证最差情况下，可以退出程序，不至于一直等待导致死锁； 2. 设置按照同一顺序访问资源，类似于串行执行；</p></li><li><p>避免事务中的用户交叉；</p></li><li><p>保持事务简短并在一个批处理中；</p></li><li><p>使用低隔离级别；</p></li><li><p>使用绑定链接。</p></li></ol><h2 id="_60-使用-mysql-的索引应该注意些什么" tabindex="-1">60. 使用 MySQL 的索引应该注意些什么？ <a class="header-anchor" href="#_60-使用-mysql-的索引应该注意些什么" aria-label="Permalink to &quot;60. 使用 MySQL 的索引应该注意些什么？&quot;">​</a></h2><p><img src="'+E+'" alt="img"></p><h2 id="_61-char-和-varchar-的区别" tabindex="-1">61. CHAR 和 VARCHAR 的区别？ <a class="header-anchor" href="#_61-char-和-varchar-的区别" aria-label="Permalink to &quot;61. CHAR 和 VARCHAR 的区别？&quot;">​</a></h2><p>CHAR 和VARCHAR 类型在存储和检索方面有所不同</p><p>CHAR 列长度固定为创建表时声明的长度，长度值范围是1 到255当 CHAR 值被存储时，它们被用空格填充到特定长度，检索CHAR 值时需删除尾随空格。</p><h2 id="_62-主键和候选键有什么区别" tabindex="-1">62. 主键和候选键有什么区别？ <a class="header-anchor" href="#_62-主键和候选键有什么区别" aria-label="Permalink to &quot;62. 主键和候选键有什么区别？&quot;">​</a></h2><p>表格的每一行都由主键唯一标识,一个表只有一个主键。主键也是候选键。按照惯例，候选键可以被指定为主键，并且可以用于任何外键引用。</p><h2 id="_63-主键与索引有什么区别" tabindex="-1">63. 主键与索引有什么区别？ <a class="header-anchor" href="#_63-主键与索引有什么区别" aria-label="Permalink to &quot;63. 主键与索引有什么区别？&quot;">​</a></h2><p>主键一定会创建一个唯一索引，但是有唯一索引的列不一定是主键；</p><p>主键不允许为空值，唯一索引列允许空值；</p><p>一个表只能有一个主键，但是可以有多个唯一索引；</p><p>主键可以被其他表引用为外键，唯一索引列不可以；</p><p>主键是一种约束，而唯一索引是一种索引，是表的冗余数据结构，两者有本</p><h2 id="_64-mysql-如何做到高可用方案" tabindex="-1">64. MySQL 如何做到高可用方案？ <a class="header-anchor" href="#_64-mysql-如何做到高可用方案" aria-label="Permalink to &quot;64. MySQL 如何做到高可用方案？&quot;">​</a></h2><p>MySQL 高可用，意味着不能一台 MySQL 出了问题，就不能访问了。</p><ol><li><p>MySQL 高可用：分库分表，通过 MyCat 连接多个 MySQL</p></li><li><p>MyCat 也得高可用：Haproxy，连接多个 MyCat</p></li><li><p>Haproxy 也得高可用：通过 keepalived 辅助 Haproxy</p></li></ol><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>全局锁/表锁</strong>：备份、<strong>DDL</strong> 场景用，日常业务基本不碰，知道有这三层锁就行。</li><li><strong>分区表</strong>：物理上把一张表按时间/范围切分，能提高<strong>大表维护</strong>效率，但和<strong>分表</strong>不是一回事。</li></ul>',177))])}const _=g(u,[["render",L]]);export{q as __pageData,_ as default};
